import os
import re
import json

VENUS_JS = r'd:\vedic-astrology-app - 2\frontend\src\data\planets\venus.js'

scorpio_data = {
    "effect": "Venus in Scorpio placement here indicates that you may have a handsome personality with an efficient work style and the ability to make quick decisions. You may have less wealth quotient, but you are practical by nature with inherent ability to perceive events in advance.\n\nYou have to travel to different destinations for professional matters and to earn money. You are likely to be blessed with a good-looking partner with whom you enjoy each other’s company. Venus in Scorpio in the first house indicates that you may enjoy strong emotional connectivity and physical intimacy with your partner.\n\nYou have the ability to work hard with quick decisions and actions to overcome personal/professional difficulties and gain success in your ventures. Venus here has the power to bless you with name and fame from the society.",
    "retrogradeEffect": "Venus represents your approach to love, beauty, and harmony in relationships where the Scorpio sign is connected with deep passion and transformation in relationships. When Venus is retrograde in Scorpio sign the energy of love and passion is concentrated more towards oneself leading to the evaluation of your own desires in relationships.\n\nRetrograde Venus in Scorpio in any natal chart gives a complex and intense approach to love relationships where there is intense need for personal space from your partner in relationships.\n\nRelationships are predominated by the intense fear of rejection and are treated with the desire of equal dedication from both partners. This period gives you some resistance/hesitancy about entering into new relationships but once committed in a relationship, individuals with retrograde Venus in Scorpio are likely to stick around for long term commitment even if they feel challenged in their relationship.",
    "combustEffect": "When Venus is combust in Scorpio, it means that Venus is in the same sign as the Sun, or it is too close to the Sun in degrees in your horoscope. When Venus is combust, it is said that it loses some of its power and individuality due to the overwhelming influence of Sun on the qualities of the combust planet.\n\nVenus represents love/marriage relationships, so combust Venus in Scorpio in any individual’s horoscope can impact love/marriage relationships and you may have trouble in searching for an appropriate partner for marriage, or relationships are likely to face turbulence in personal front and in social interactions with others.\n\nCombust Venus in Scorpio obscures your ability to make sound decisions related to relationships, finances and partnership where you are unable to judge the authenticity of any relationships/situation.\n\nWhen Venus is combust in Scorpio in the beneficial position with Sun, it can bless you with good results related to marriage, profession, authority, fame, and other aspects of life depending on the overall planetary configuration of your horoscope.\n\nOn the other hand, the malefic association of Sun with Venus in Scorpio can give problems related to your health, profession, marriage where you may have to face financial losses due to your impulsive behaviour.",
    "houses": {
        "1": "Venus in Scorpio placement here indicates that you may have a handsome personality with an efficient work style and the ability to make quick decisions. You may have less wealth quotient, but you are practical by nature with inherent ability to perceive events in advance. You have to travel to different destinations for professional matters and to earn money. You are likely to be blessed with a good-looking partner with whom you enjoy each other’s company. Venus in Scorpio in the first house indicates that you may enjoy strong emotional connectivity and physical intimacy with your partner.\n\nYou have the ability to work hard with quick decisions and actions to overcome personal/professional difficulties and gain success in your ventures. Venus here has the power to bless you with name and fame from the society.",
        "2": "Venus in Scorpio here brings a transformative energy to your relationships and finances. In terms of your relationships, you have deep emotions for your partner and crave strong connectivity with them. You lack interest in superficial relations but seek a bond with the same intensity from your partner, which may lead to possessiveness and jealousy in relationships. You may face struggle with the fear of losing your partner, but it is necessary to balance your mutual trust with your partner through open communication over your personal issues.\n\nIf you have established yourself in any commitment, you are dedicated and loyal in your relationship where you are willing to work hard to protect and support your partner in all circumstances. In terms of your finances, you have the strong desire for financial security and stability where you will invest your energy to accumulate wealth and materialistic possessions that give you the sense of comfort and power of control.\n\nYour personal values are ruled by your emotional instincts, where you show strong sentiments for possessions, but when it comes to making any emotional decisions, you trust your own instinct and intuition to guide you in the right direction that aligns with your needs and desires.",
        "3": "Venus in Scorpio here indicates a strong and effective way of communicating and connecting with others where your words have the ability to impress others and the others are inspired to follow your instructions without any opposition and make them work for you with unconditional dedication. You have a sharp and analytical mind which facilitates you to pick out the undefined motives and emotions of others while interacting. You have the unique ability to understand others at a profound level with insight to understand their true feelings despite their efforts to hide it.\n\nYour words carry a magnetic effect because your expression is passionate and convincing, which attracts others towards you. You seek intensity and depth in your personal/love relationships where your words have the power of evoking strong emotions that can create strong impact on your partner’s mind. Be mindful when using your communication skills with balance of diplomacy and sensitivity to make your relationships healthy.\n\nYour daring attitude and initiative are your strong assets, but it is important to remember that everyone may not be ready to respond to your strong passion in relationships, so it is important to learn to respect other boundaries and allow them to connect their emotions at their own pace and that will bless you with harmony in your relationships.",
        "4": "Venus in Scorpio here signifies deep and intense emotional connectivity in your personal life and relationships, where you have a strong desire for emotional security and establish strong connections with your family and loved ones. You are very possessive about maintaining your sense of privacy and have the tendency to keep your personal relationships and home life hidden from public eyes. You have a strong attachment with your family, with the feeling of loyalty and protectiveness towards them.\n\nYour emotional instinct towards your loved ones is strong and deep; you are protective towards their flaws and love to support them even in adverse situations. This loyalty towards your family can bring strong emotional connections with them, but it can also bring about your possessiveness and domination in relationships. Your sensual nature attracts others as you have the natural ability to understand the desires and needs of others, which can make you an attentive and caring partner but on the other hand, it can make you jealous and possessive in relationships.\n\nOverall, your home and family are very important to you, and you aspire to create a nurturing and secure family environment for yourself and your loved ones, but you must be cautious as it can make you struggle with trust and possessiveness in relationships.",
        "5": "Venus in Scorpio here brings deep passion to your love life, creativity, and interaction with children or younger siblings, where you possess a natural charm that attracts others towards you. Your knack to reach the depths of emotions of others sets you apart from others; it has the skill to create meaningful connections with your ability to express your emotions freely to your partner and loved ones. This placement can bring passion with deep intensity in your romantic relationships and creative endeavors.\n\nYou will have a love life that is very intense and filled with emotional ups and downs, but you desire a partner who has the ability to reciprocate your emotions with equal intensity and depth. However, be vigilant that your high expectations do not make you overly possessive or jealous in relationships. Your creative expression has the power to impress others, and your nurturing instincts are strong towards your children, young siblings, and young generation, which may make you guide them, which will have a significant impact on their progress.\n\nYou have the natural charisma to attract others on the social platform where you value your privacy in relationships but value loyalty and emotional depth in your relationships; you do not like to invest your energies in superficial connections.",
        "6": "Venus in Scorpio here brings the exclusive blend of energies that influence your approach in your relationships, work, and daily routine. You have an intense way of expressing your love and affection, and strong desire for emotional connection or intimacy with your partner. You seek strong connections in your relationships, and you are attracted towards a partner who can match your intensity in intimate relationship. On the other hand, this intensity can lead to possessiveness and jealousy towards your partner, so it's important for you to find a balance and avoid becoming too controlling and possessive in your relationships.\n\nYou have strong work ethics and are dedicated in your work approach in achieving your professional goals. You have a strong focus on your career endeavors and have the ability to ensure that your work is done meticulously. So, it is essential to create balance between your dedication on the work front and taking plenty of rest and relaxation for your mental and physical rejuvenation. In terms of health, you may be interested in making modifications in your diet and following the daily routine of practicing yoga and meditation for mental and physical fitness.",
        "7": "Venus in Scorpio here talks about deep intensity and passion in your personal relationships. In partnership, you aspire for genuine connection rather than superficial relations that do not work for you in any relationship. You are intense and emotional by nature, which gives you the inherent tendency to become possessive or jealous in relationships. This trait may disturb your partner/spouse as you expect the same level of dedication, but it is important for you to balance your fear of losing your relationship and allow your partner the freedom they need to avoid being possessive in a love relationship.\n\nYou have a strong sexual orientation with your partner, and you are aware of the influence of physical intimacy. You use it to build a strong emotional bond with your partner in love relationships, who will reciprocate your gestures with the same intensity. You have a strong belief that relationships/partnerships may go through fluctuations, but you do not shy away from difficult situations or relationships but believe in rectifying your issues with communication over the matter of concern.\n\nYour intensity may be overwhelming at times in relationships, but it also gives you a chance to make changes in certain aspects to have fulfilling relationships /partnerships with others.",
        "8": "Venus in Scorpio here indicates your hidden passion in your physical intimacy with your partner/spouse, where you have a deep craving to explore the emotions of your partner to form strong connections that may have the potential to bring bonding in your personal equations with your partner. On the other hand, your tendency to become jealous can create trust issues with your partner, so it is necessary for you to maintain balance for the harmony and emotional security of your relationship.\n\nVenus in Scorpio here can bless you with financial opportunities from shared resources and joint ventures. You may have the responsibility of managing your spouse’s or partner’s family money/investments, which can bring financial stability in your life. You are loyal and committed to close relationships/friendships, where you will make efforts and invest your time and energy to nurture your relationships to form long-lasting bonds with your partner and a small group of good friends.",
        "9": "Venus in Scorpio here will bless you with deep intensity in your personal relationships. This placement of Venus brings the passionate energy of your emotions to combine with the deep strength of your emotions that has the ability to influence your romantic relations with your partner with a more understanding approach despite being very demanding and possessive in nature. In matters of love, you desire for deep intimacy and strong emotional connection that can lead you to be assertive in relations due to the fear of losing the love equation with your partner that you have established. You have a demanding and possessive approach in your personal relationships too.\n\nOn the other hand, once the connection with your partner/family is established that can match your intensity and commitment, you are capable of giving everyone love and loyalty. You will have a fascination for long travels where you would like to accumulate information to broaden your perspective and gain a deeper understanding. You have a strong desire to explore and uncover mysteries in situations/relationships.\n\nSo, this placement of Venus in Scorpio suggests you embrace transformation in your nature while maintaining a balance in your relationship to experience love and a healthy connection with your partner.",
        "10": "Venus in Scorpio here indicates a blend of strong emotions, ambitions, and the magnetic charm in your personality that has the power to attract others towards you. You hold a deep desire for success and recognition in your career, and you will make the necessary efforts to achieve your goals. Your profession and public image are very important for your social recognition. You have the ability to navigate and solve your problems with your deep knowledge and the ability to overcome your problems in your career and overrule your professional rivals with tact and assertion of your point to succeed.\n\nYou may be attracted to careers related to psychology, research, and everything that allows you to uncover hidden truths. Your ability to connect with others on a deep level can also make you an excellent leader, a good mentor, and guide. In relationships, you desire strong and deep emotional connections with your partner and loved ones, where you will make a lot of efforts and actions to make your relationships work once you’re committed in relations.\n\nVenus in Scorpio makes you focus on power and control, where the urge to win over others can make you strongly competitive in your journey for professional success. Your magnetic charm and intensity in your emotions can attract others towards you, but it is necessary to balance your professional success and harmony in relationships with adjustments on both levels.",
        "11": "Venus in Scorpio here makes you give importance to your friendships and social connections, where your charm attracts others and you have the ability to form deep emotional bonds with others, which is unique. You are known for your trust and unconditional support, and you value trust and honesty in friendship with the same level of commitment from those close to you. You are not interested in superficial connections but make adjustments in relationships that have the potential to make changes in your life. You love to connect with people with hidden aspects of their personalities where you enjoy learning about their true selves.\n\nYour romance in relationships has the craving for intense connections with that partner who can match your level of passion. You are not satisfied with casual relationships but seek deep connectivity in relationships. However, your desire for emotional depth can at times lead to possessiveness in relationships/friendship due to your fear of losing your close ones, so it is necessary to cultivate an open and honest communication with your partner/close relations to avoid misunderstandings and build trust and confidence in each other.",
        "12": "Venus in Scorpio here indicates your need for privacy and solitude due to the over connection with the world activities and relationships. You may feel the urge for introspection and self-realization trying to unveil your real ambitions, and outlook, or the truths about yourself. On the other hand, this placement can bring challenges in your relations and self-expression of your emotions, where you may struggle to trust others and become more introverted in your nature.\n\nIt is very important for you to work on building trust and making yourself more understanding towards those you care about. Giving space to your partner/loved ones can help you maintain profound connection and be blessed with emotional contentment in your relationships. It’s important for you to find balance between your desire to maintain deep connections in relationships, and being possessive in your relationships."
    },
    "remedies": []
}

with open(VENUS_JS, 'r', encoding='utf-8') as f:
    content = f.read()

signs_match = re.search(r'signs:\s*\{', content)
if signs_match:
    insertion_point = signs_match.end()
    scorpio_json = "      Scorpio: " + json.dumps(scorpio_data, indent=8) + ","
    new_content = content[:insertion_point] + "\n" + scorpio_json + content[insertion_point:]
    
    with open(VENUS_JS, 'w', encoding='utf-8') as f:
        f.write(new_content)
    print("Added Venus in Scorpio to venus.js")
else:
    print("Could not find signs object in venus.js")
